INSERT OR IGNORE INTO tesla_alert_catalog (signal_name, models, condition, clear_condition, description, potential_impact, customer_message_1, customer_message_2, audiences, source_row) VALUES
  ('ADSP_w002_exception', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP detected an exception in one of the processor cores either on boot or during runtime.', 'The exception condition was resolved and the processor core can resume normal operation.', 'A processor exception was detected by the Audio Digital Signal Processor (ADSP) exception handler.', 'Audio system functionality may be degraded or unavailable. Exception may indicate a critical error that requires processor reset.', 'Not Available', 'Not Available', 'service', 2),
  ('ADSP_w022_emacErr', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The ADSP detects an EMAC error. Alert log signal data provides information on the specific condition(s) detected.', 'The ADSP no longer detects an EMAC error.', 'The Audio Digital Signal Processor (ADSP) detects an Ethernet Media Access Controller (EMAC) error.', 'The Active Noise Canceling (ANC) feature may be unavailable or may not operate as expected.', 'Not Available', 'Not Available', 'service', 3),
  ('ADSP_w033_a2baDiscoveryFailed', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP has was unable to detect or discover A2B-A.', 'Successful A2B discovery.', 'The Audio Digital Signal Processor (ADSP) was unable to discover A2B-A.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 4),
  ('ADSP_w034_a2bbDiscoveryFailed', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP has was unable to detect or discover A2B-B', 'Successful A2B discovery.', 'The Audio Digital Signal Processor (ADSP) was unable to discover A2B-B.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 5),
  ('ADSP_w035_a2baFault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP detects a condition with A2B-A.', 'A2B condition is cleared.', 'The Audio Digital Signal Processor (ADSP) has detected a condition in A2B-A.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 6),
  ('ADSP_w036_a2bbFault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP detects a condition with A2B-B.', 'A2B condition is cleared.', 'The Audio Digital Signal Processor (ADSP) has detected a condition in A2B-B.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 7),
  ('ADSP_w037_a2baIdleFailed', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'A2B-A idle error detected.', 'A2B idle error is cleared.', 'The Audio Digital Signal Processor (ADSP) has detected an A2B-A idle error.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 8),
  ('ADSP_w038_a2bbIdleFailed', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'A2B-A idle error detected.', 'A2B idle error is cleared.', 'The Audio Digital Signal Processor (ADSP) has detected an A2B-B idle error.', 'Audio system functionality may not operate as expected.', 'Not Available', 'Not Available', 'service', 9),
  ('ADSP_w050_extSpkFault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'ADSP detects an electrical condition preventing external speaker functionality.', 'ADSP no longer detects an electrical condition.', 'The Audio Digital Signal Processor (ADSP) has detected an electrical condition condition preventing functionality of the external speakers.', 'Pedestrian Warning System (PWS), horn, and other external speaker functions may not operate as expected.', 'External speaker fault', 'Service is required', 'service-fix', 10),
  ('ADSP_w053_audioSystemUnavailable', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'One of the required monitored audio subsystem is not available or malfunctioning', 'Audio system functions restored', 'The audio system is currently unavailable. The horn and / or chimes may not function.', 'Audio system may not operate as expected. Horn and / or chimes may not function', 'Audio system unavailable - Horn and/or chimes may not function', 'Schedule service if audio system does not recover', 'customer;service-fix', 11),
  ('ADSP_w066_rearPwsFault', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'ADSP has detected a fault condition preventing RPWS speaker functionality.', 'RPWS speaker and/or wiring are repaired and ADSP no longer detects the fault condition causing loss of functionality.', 'The Audio Digital Signal Processor (ADSP) has detected a fault condition preventing functionality of the Rear Pedestrian Warning System (RPWS).', 'RPWS functions may not work.', 'External speaker fault', 'Service is required', 'service-fix', 12),
  ('ADSP_w067_baseamp0Fault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'A electrical fault has been detected in the base amplifier, possible causes include under-voltage, over-voltage, over-current, over-temperature, clock Phase-Locked Loop issues, or DC offset errors.', 'The base amplifier electrical fault has been cleared, and normal operation has been restored.', 'A electrical fault has been detected in the base amplifier.', 'Compromised audio performance, signal degradation, or complete loss of audio functionality.', 'Not Available', 'Not Available', 'service', 13),
