  ('APP_w224_accCameraCalibration', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'One or more of the main and/or narrow cameras is not calibrated.', 'The vehicle is driven manually to allow the main and/or narrow camera(s) to finish calibrating.', 'One or more of the main and/or narrow cameras is not calibrated, which may cause Traffic-Aware Cruise Control (TACC) functionality to be limited or unavailable.', 'Traffic-Aware Cruise Control (TACC) functionality may be limited or unavailable.', 'Cruise control unavailable', 'Continue driving to allow cameras to calibrate', 'customer;service', 229),
  ('APP_w225_lcDegradedVisSpeedLmt', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'One or more of the main and/or narrow camera pitches is out of bounds, which may cause Traffic-Aware Cruise Control (TACC) functionality to be limited or unavailable.', NULL, 'Self-Driving / Active Safety features unavailable', 'Camera alignment required - Schedule service', 'customer;service-fix', 230),
  ('APP_w225_lcDegradedVisSpeedLmt', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'One or more of the main and/or narrow camera pitches is out of bounds.', 'The main and/or narrow camera(s) are recalibrated.', 'One or more of the main and/or narrow camera pitches is out of bounds, which may cause Traffic-Aware Cruise Control (TACC) functionality to be limited or unavailable.', 'Traffic-Aware Cruise Control (TACC) functionality may be limited or unavailable.', 'Self-Driving / Active Safety features unavailable', 'Camera alignment required - Schedule service', 'customer;service-fix', 231),
  ('APP_w229_alcUltrasoundDamaged', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Automatic lane change (ALC) is initiated by the driver but ALC is unavailable due to Autopilot electronic control unit (ECU) detecting damage to ultrasonic sensors.', NULL, 'Not Available', 'Not Available', 'customer;service-fix', 232),
  ('APP_w229_alcUltrasoundDamaged', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'Autopilot ECU detects damage to one or more ultrasonic sensors while ALC is initiated.', 'Autopilot ECU no longer detects any damage to ultrasonic sensors.', 'Auto lane change (ALC) is unavailable due to Autopilot electronic control unit (ECU) detecting damage to ultrasonic sensors.', 'Auto lane change (ALC) feature is unavailable.', 'Not Available', 'Not Available', 'service-fix', 233),
