  ('APP_w264_lssFault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'A condition is detected that affects Lane Support System (LSS) functionality. The alert log signals will provide more specific details.', 'The alert will clear when the condition affecting Lane Support System (LSS) functionality is corrected / no longer present.', 'Lane Support System (LSS) has encountered a condition making Lane Departure Warning and Emergency Lane Departure Warning features unavailable.', 'Lane Departure Warning and Emergency Lane Departure Warning features will be unavailable.', 'Lane Departure Avoidance features unavailable', 'Features may be restored on next drive', 'customer;service', 248),
  ('APP_w265_drvOnNavUnavailable', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot electronic control unit (ECU) detects a condition that makes Navigate on Autopilot unavailable.', NULL, 'Navigate on Autosteer currently unavailable', 'Features may be restored on next drive', 'customer;service', 249),
  ('APP_w265_drvOnNavUnavailable', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'A condition is detected that makes Navigate on Autopilot unavailable. The alert log signals will provide more details on the condition.', 'This alert will clear when the condition making Navigate on Autopilot unavailable is no longer present.', 'The Autopilot electronic control unit (ECU) detects a condition that makes Navigate on Autopilot unavailable.', 'Navigate on Autopilot will not be available.', 'Navigate on Autosteer currently unavailable', 'Features may be restored on next drive', 'customer;service', 250),
  ('APP_w266_visionScheduleFallback', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot electronic control unit (ECU) has detected a reduction in vision or a potential blocking of the side cameras. Automatic lane changes and blind spot assist are unavailable.', NULL, 'Not Available', 'Not Available', 'service', 251),
