  ('APS_w129_ECU_Power_Issue', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Secondary warns when one or more voltage rails fail to reach expected voltage level.', NULL, 'Not Available', 'Not Available', 'service-fix', 510),
  ('APS_w129_ECU_Power_Issue', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'One or more voltage rails fail to reach expected voltage level.', 'All voltage rails report expected voltage levels.', 'Autopilot Processor Secondary warns when one or more voltage rails fail to reach expected voltage level.', 'Some Autopilot components may not be powered correctly.', 'Not Available', 'Not Available', 'service-fix', 511),
  ('APS_w130_ECU_Thermal_Issue', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopoilot Processor Secondary warns when temperature of Autopilot (AP) board exceeds thresholds.', NULL, 'Not Available', 'Not Available', 'service-fix', 512),
  ('APS_w130_ECU_Thermal_Issue', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'AP temperature goes beyond thresholds.', 'AP board temperature is within normal range.', 'Autopoilot Processor Secondary warns when temperature of Autopilot (AP) board exceeds thresholds. .', 'AP will shutdown, leading to loss of AP features if temperature goes above threshold.', 'Not Available', 'Not Available', 'service-fix', 513),
  ('APS_w132_appVersionMismatch', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Primary (APP) firmware (FW) version does not match the Autopilot Processor Secondary (APS) version, making Autopilot (AP) features unavailable.', NULL, 'Software update required', 'Schedule service', 'customer;service-fix', 514),
  ('APS_w132_appVersionMismatch', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APP FW version does not match the APS FW version.', 'APS and/or APP FW is updated to match the vehicle FW version.', 'Autopilot Processor Primary (APP) firmware (FW) version does not match the Autopilot Processor Secondary (APS) version, making Autopilot (AP) features unavailable.', 'AP features will be unavailable.', 'Software update required', 'Schedule service', 'customer;service-fix', 515),
  ('APS_w133_ETHSwitchError', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Secondary (APS) has not initialized the Ethernet switch correctly.', NULL, 'Not Available', 'Not Available', 'service', 516),
  ('APS_w133_ETHSwitchError', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'Ethernet switch programming fails or returns error.', 'Ethernet switch is correctly initialized.', 'Autopilot Processor Secondary (APS) has not initialized the Ethernet switch correctly.', 'Autopilot communication over Ethernet will be broken.', 'Not Available', 'Not Available', 'service', 517),
  ('APS_w134_appMia', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Secondary (APS) has not received one or more messages from the Autopilot Processor Primary (APP), making Autopilot (AP) features unavailable.', NULL, 'Not Available', 'Not Available', 'service', 518),
  ('APS_w134_appMia', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more messages from the APP.', 'APS starts receiving all messages from APP at the expected rate.', 'Autopilot Processor Secondary (APS) has not received one or more messages from the Autopilot Processor Primary (APP), making Autopilot (AP) features unavailable.', 'AP features will be unavailable.', 'Not Available', 'Not Available', 'service', 519),
  ('APS_w135_appCritical', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Secondary (APS) detects that the Autopilot Processor Primary (APP) is not functioning as expected, making Autopilot (AP) features unavailable.', NULL, 'Not Available', 'Not Available', 'service-fix', 520),
  ('APS_w135_appCritical', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS detects the state of APP is not optimal based on watchdog state or general-purpose input/outputs (GPIOs).', 'APP is detected to be functioning as expected.', 'Autopilot Processor Secondary (APS) detects that the Autopilot Processor Primary (APP) is not functioning as expected, making Autopilot (AP) features unavailable.', 'AP features will be unavailable.', 'Not Available', 'Not Available', 'service', 521),
  ('APS_w136_gpsDisabled', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot electronic control unit (ECU) detects a condition affecting the functionality of the GPS receiver.', NULL, 'Not Available', 'Not Available', 'service-fix', 522),
  ('APS_w136_gpsDisabled', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The Autopilot ECU detects a condition affecting the functionality of the GPS receiver. Alert log signal data should provide more information on specific condition(s) detected.', 'The Autopilot ECU no longer detects a condition affecting the functionality of the GPS receiver.', 'The Autopilot electronic control unit (ECU) detects a condition affecting the functionality of the GPS receiver.', 'Autopilot features depending on GPS may not be available, or may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 523),
  ('APS_w137_gpsFaultReset', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot Processor Secondary (APS) detects the GPS receiver was reset, causing a temporary reduction in location accuracy.', NULL, 'Not Available', 'Not Available', 'service', 524),
  ('APS_w137_gpsFaultReset', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The GPS receiver was reset. Alert log signal data should provide more information on the specific condition(s) detected.', 'Clears automatically after the GPS resets.', 'The Autopilot Processor Secondary (APS) detects the GPS receiver was reset, causing a temporary reduction in location accuracy.', 'Autopilot features depending on GPS may be unavailable, or may not function as expected. The GPS marker may be temporarily inaccurate.', 'Not Available', 'Not Available', 'service', 525),
  ('APS_w138_gpsComIssue', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Autopilot Processor Secondary (APS) detects communication issues with the GPS receiver.', NULL, 'Not Available', 'Not Available', 'service', 526),
  ('APS_w138_gpsComIssue', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS detects a fault in GPS communication.', 'GPS receiver communication is re-established.', 'Autopilot Processor Secondary (APS) detects communication issues with the GPS receiver.', 'Navigation and Autosteer will be temporarily broken.', 'Not Available', 'Not Available', 'service', 527),
  ('APS_w139_udpBufferOverflow', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'APS_w139_udpBufferOverflow', NULL, 'Not Available', 'Not Available', 'service', 528),
  ('APS_w140_vcfrontMiaVehicleBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from VCFRONT on the Vehicle Bus.', 'APS starts receiving all CAN messages from VCFRONT.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from the front vehicle controller (VCFRONT) on the Vehicle Bus. Autopilot (AP) will not boot completely if this occurs at startup. If AP is already running, Auto Lane Change (ALC) will be unavailable.', 'If this condition occurs at startup, AP will not boot completely. If this condition occurs while AP is already running, ALC will be unavailable.', 'Not Available', 'Not Available', 'service', 529),
  ('APS_w141_rcmMiaPartyBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from RCM on Party Bus.', 'APS starts receiving all CAN messages from RCM.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from Restraint Control Module (RCM) on Party Bus.', 'Autopilot features will be disabled since APS forwards these messages to radar.', 'Not Available', 'Not Available', 'service', 530),
