  ('APS_w143_espMiaPartyBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not to receive one or more CAN messages from ESP on Party Bus.', 'APS starts receiving all CAN messages from ESP.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from Electronic Stability Program (ESP) on Party Bus.', 'Autopilot features will be disabled since APS forwards these messages to radar.', 'Not Available', 'Not Available', 'service', 532),
  ('APS_w144_vcleftMiaPartyBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from VCLEFT on Party Bus.', 'APS starts receiving all CAN messages from VCLEFT.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from left vehicle controller (VCLEFT) on Party Bus.', 'Autopilot features will be disabled since APS forwards these messages to radar.', 'Not Available', 'Not Available', 'service', 533),
