  ('APS_w146_epas3pMiaPartyBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from Primary EPAS3 on Party Bus.', 'APS starts receiving all CAN messages from Primary EPAS3.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from Primary Electronic Power Assisted Steering Gear (EPAS3) on Party Bus.', 'Autopilot features will be disabled since APS forwards these messages to radar.', 'Not Available', 'Not Available', 'service', 536),
  ('APS_w147_vcleftMiaVehBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from VCLEFT on the Vehicle Bus.', 'APS starts receiving all CAN messages from VCLEFT.', 'Autopilot Processor Secondary (APS) has not recieved one or more Controller Area Network (CAN) messages from the left vehicle controller (VCLEFT) on the Vehicle Bus, making Autopilot (AP) features unavailable.', 'Autopilot features will be unavailable since APS forwards these messages to other electronic control units, including radar.', 'Not Available', 'Not Available', 'service', 537),
  ('APS_w148_vcrightMiaVehBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not receive one or more CAN messages from VCRIGHT on the Vehicle Bus.', 'APS starts receiving all CAN messages from VCRIGHT.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from the right vehicle controller (VCRIGHT) on the Vehicle Bus, making Autopilot (AP) features unavailable.', 'AP features will be unavailable because APS forwards these messages to other electronic control units, including radar.', 'Not Available', 'Not Available', 'service', 538),
  ('APS_w149_epblMiaVehBus', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'APS does not to receive one or more CAN messages from EPBL on Vehicle Bus.', 'APS starts receiving all CAN messages from EPBL.', 'Autopilot Processor Secondary (APS) has not received one or more Controller Area Network (CAN) messages from Electronic Park Brake left (EPBL) on Vehicle Bus.', 'Autopilot features will be disabled since APS forwards these messages to radar.', 'Not Available', 'Not Available', 'service', 539),
