  ('APS_w166_TurboA_SMSLockStepErr', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot (AP) electronic control unit (ECU) detects that the Turbo A main processor encounters a lockstep error in the safety management subsystem (SMS).', NULL, 'Not Available', 'Not Available', 'service', 557),
  ('APS_w166_TurboA_SMSLockStepErr', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The AP ECU detects a lockstep error on the Turbo A main processor in the SMS.', 'Clears when the lockup error is no longer detected on the Turbo A main processor in the SMS.', 'The Autopilot (AP) electronic control unit (ECU) detects that the Turbo A main processor encounters a lockstep error in the safety management subsystem (SMS).', 'All AP features will be unavailable.', 'Not Available', 'Not Available', 'service', 558),
  ('APS_w169_TurboA_SCS_LKUP', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot (AP) electronic control unit (ECU) detects that the Turbo A main processor encounters a lockup error in the security controller subsystem (SCS), which causes the AP ECU to reboot.', NULL, 'Not Available', 'Not Available', 'service-fix', 559),
  ('APS_w169_TurboA_SCS_LKUP', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The AP ECU detects a lockup error on the Turbo A main processor in SCS, causing the AP ECU to reboot.', 'Clears after the AP ECU finishes rebooting, and a lockup error is no longer detected on the Turbo A main processor in SCS.', 'The Autopilot (AP) electronic control unit (ECU) detects that the Turbo A main processor encounters a lockup error in the security controller subsystem (SCS), which causes the AP ECU to reboot.', 'All AP features will be unavailable.', 'Not Available', 'Not Available', 'service-fix', 560),
  ('APS_w170_TurboA_A72_watchdog', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'The Autopilot (AP) electronic control unit (ECU) detects a watchdog event on the Turbo A main processor, which causes the AP ECU to reboot.', NULL, 'Not Available', 'Not Available', 'service', 561),
  ('APS_w170_TurboA_A72_watchdog', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The AP ECU detects a watchdog event on the Turbo A main processor, causing the AP ECU to reboot.', 'Clears after the AP ECU finishes rebooting, and a watchdog event is no longer detected on the Turbo A main processor.', 'The Autopilot (AP) electronic control unit (ECU) detects a watchdog event on the Turbo A main processor, which causes the AP ECU to reboot.', 'All AP features will be unavailable.', 'Not Available', 'Not Available', 'service', 562),
