  ('BCFALCD_a261_USS_RoofOverTemp', 'Model X 2021+', 'The Falcon Door Roof USS is detected with elevated temperature readings.', 'Temperature readings return to within normal thresholds.', 'CThe Falcon Door Roof Ultra-Sonic Sensor (USS) over temperature condition detected.', 'Persistent over temperature conditions in roof USS may result in inaccurate proximity detection, damage to USS, and impaired Falcon Door functionality.', 'Not Available', 'Not Available', 'service', 775),
  ('BCFALCD_a262_USS_RoofSnsIntFail', 'Model X 2021+', 'The USS controller detects an internal condition on the roof USS.', 'The USS controller does not detect an internal condition on the roof USS.', 'The ultrasonic sensor (USS) controller detects an internal condition affecting the roof USS.', 'The roof USS may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 776),
  ('BCFALCD_a263_USS_RoofLinComError', 'Model X 2021+', 'The USS controller detects a condition affecting the LIN communication with the roof USS.', 'The USS controller does not detect a condition affecting the LIN communication with the roof USS.', 'The ultrasonic sensor (USS) controller detects a condition affecting the Local Interconnect Network (LIN) communication with the roof USS.', 'The roof USS may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 777),
