  ('BCFALCD_a266_USS_SnsSupplyError', 'Model X 2021+', 'Alert log signal data should provide further information on specific condition(s) involved.', 'Supply error cleared after passing diagnostics checks.', 'An anomaly pertaining to power delivery has been detected in the Falcon Door Ultrasonic Sensor''s (USS) circuitry.', 'A supply error could result in intermittent or total loss of functionality of the USS.', 'Not Available', 'Not Available', 'service', 780),
  ('BCFALCD_a267_USS_ECUIntrnlFailur', 'Model X 2021+', 'An internal error was detected in the USS ECU.', 'Internal error in the USS ECU is not longer detected.', 'The Falcon Door Ultra-Sonic Sensor (USS) Electronic Control Unit (ECU) has experienced an internal error.', 'An internal error could result in intermittent or total loss of functionality of the USS.', 'Not Available', 'Not Available', 'service-fix', 781),
  ('BCFALCD_a268_USS_calibCRCFailure', 'Model X 2021+', 'A CRC failure has been detected in the USS calibration.', 'USS calibration CRC failure is no longer present.', 'The Falcon Door Ultra-Sonic Sensor (USS) calibration has experienced a Cyclic Redundancy Check (CRC) failure condition.', 'A CRC failure could result in intermittent, total loss, or reduced functionality of the USS.', 'Not Available', 'Not Available', 'service', 782),
