  ('BCFDM_a010_ExtSupplyVoltError', 'Model X 2021+', 'The vehicle controller detects the supply voltage from 1 or more components is < 7.31. Alert log signal data should provide more information on the specific condition(s) detected.', 'The vehicle controller detects the supply voltage from all components is > 7.31 V.', 'The vehicle controller detects the supply voltage from 1 or more components is outside of the expected range.', 'Features depending on the vehicle controller functionality may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service', 1110),
  ('BCFDM_a015_NVMMError', 'Model X 2021+', 'Non-volatile memory misconfiguration or underlying flash/filesystem error.', 'Bootup without indication.', 'An issue is indicated from the non-volatile memory manager.', 'Non-volatile memory records may be incorrect or missing.', 'Not Available', 'Not Available', 'service', 1111),
  ('BCFDM_a059_inputResistanceHigh', 'Model X 2021+', 'Estimated resistance on the input power feed to the vehicle controller is higher than expected.', 'Estimated resistance on the input power feed to the vehicle controller is no longer higher than expected.', 'A large voltage drop is detected in the input power to the vehicle controller, indicating the resistance on the input power feed to the vehicle controller is higher than expected.', 'The vehicle controller may be unavailable due to lack of adequate input power, limiting vehicle functionality or making the vehicle inoperable, with at least one other alert specific to that condition present.', 'Not Available', 'Not Available', 'service-fix', 1112),
