  ('BMS_d274_packCurrentSensorACircuitFailure', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The BMS has detected the shunt hardware is unable to communicate or provide a current measurement.', NULL, 'The Battery Management System (BMS) has detected that the shunt is no longer able to provide full functionality due to a current sensor circuit issue.', 'Vehicle is unable to support the low voltage system and unable to start drive or charge.', 'Not Available', 'Not Available', 'service-fix', 2276),
  ('BMS_d275_packPosContactorACircuitFailure', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The BMS detects a circuit issue with the positive pack contactor.', NULL, 'The Battery Management System (BMS) has detected the positive pack contactor has fallen open even though it was requested to be closed due to a circuit issue.', 'Vehicle is unable to start, charge or support the low voltage system.', 'Not Available', 'Not Available', 'service-fix', 2277),
