  ('DAS_w009_aebFault', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'DAS_w009_aebFault', NULL, 'Automatic Emergency Braking is unavailable', 'Feature may be restored on next drive', 'customer;service-fix', 3306),
  ('DAS_w010_radcCalibIssue', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'DAS_w010_radcCalibIssue', NULL, 'Not Available', 'Not Available', 'service-fix', 3307),
