  ('EBS_a480_ebsRedStopLamp', 'Semitruck', NULL, NULL, 'EBS Red Stop Lamp warning.', NULL, 'Electronic braking system is in backup mode', 'Drive with caution', 'service', 6021),
  ('EBS_a481_ebsNotFullyOp', 'Semitruck', NULL, NULL, 'EBS not fully operational.', NULL, 'Not Available', 'Not Available', 'service', 6022),
  ('EBS_a482_absNotFullyOp', 'Semitruck', NULL, NULL, 'ABS not fully operational.', NULL, 'ABS (anti-lock braking system) disabled', 'Drive with caution', 'customer;service', 6023),
  ('EBS_a483_vdcNotFullyOp', 'Semitruck', NULL, NULL, 'VDC not fully operational.', NULL, 'Stability control disabled', 'Drive with caution', 'customer;service', 6024),
  ('EFUSE_w001_WatchdogReset', 'Model S 2012-2020;Model X 2015-2020', 'A watchdog (external or internal) was not serviced in time.', 'Next reboot after alert is present.', 'Warns if the processor has experienced a reset due to watchdog reset.', 'Controller is MIA for some time.', 'Not Available', 'Not Available', 'service', 6025),
  ('EFUSE_w002_PowerLossReset', 'Model S 2012-2020;Model X 2015-2020', 'Sudden power loss.', 'Next reboot after alert is present.', 'Warns if the processor has experienced a reset due to power loss.', 'Controller is MIA for some time.', 'Not Available', 'Not Available', 'service', 6026),
  ('EFUSE_w003_SWAssertion', 'Model S 2012-2020;Model X 2015-2020', 'Failure of a software assertion.', 'Auto clears after 10ms of no new assertions.', 'An internal software assertion has failed.', 'Unknown.', 'Not Available', 'Not Available', 'service', 6027),
  ('EFUSE_w005_CANTXError', 'Model S 2012-2020;Model X 2015-2020', 'CAN configuration issues (invalid driver configuration), CAN driver issues (errors transmitting, queue full).', 'Cleared when error conditions are no longer present.', 'An error has been detected with CAN transmission. Used by engineering to debug.', 'Failure to send messages.', 'Not Available', 'Not Available', 'service', 6028),
  ('EFUSE_w010_ExtSupplyVoltError', 'Model S 2012-2020;Model X 2015-2020', 'The vehicle controller detects the supply voltage from 1 or more components is < 7.31. Alert log signal data should provide more information on the specific condition(s) detected.', 'The vehicle controller detects the supply voltage from all components is > 7.31 V.', 'The vehicle controller detects the supply voltage from 1 or more components is outside of the expected range.', 'Features depending on the vehicle controller functionality may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service', 6029),
  ('EFUSE_w012_CPUReset', 'Model S 2012-2020;Model X 2015-2020', 'Reset can be caused by: Clock Error, Flash Error, Software Reset, Checkstop Reset, Debug Reset', 'Next reboot after alert is present.', 'CPU detected a reset.', 'Controller is MIA for some time.', 'Not Available', 'Not Available', 'service', 6030),
  ('EFUSE_w013_AlertManagerFault', 'Model S 2012-2020;Model X 2015-2020', 'When an error occurs. For QueueFull, when the queue is full and no more alerts can be processed.', 'When error condition is no longer present. For QueueFull, when queue is no longer full.', 'Alert Manager encountered an internal processing error.', 'Alerts are not sent.', 'Not Available', 'Not Available', 'service', 6031),
  ('EFUSE_w015_NVMMError', 'Model S 2012-2020;Model X 2015-2020', 'Non-volatile memory misconfiguration or underlying flash/filesystem error.', 'Bootup without indication.', 'An issue is indicated from the non-volatile memory manager.', 'Non-volatile memory records may be incorrect or missing.', 'Not Available', 'Not Available', 'service', 6032),
  ('EFUSE_w016_NVMMRecordError', 'Model S 2012-2020;Model X 2015-2020', 'Non-volatile memory record not found, CRC mismatch, version mismatch, version upgrade.', 'Bootup without indication.', 'An issue is indicated from a particular non-volatile memory record.', 'The particular non-volatile memory record may be incorrect or missing.', 'Not Available', 'Not Available', 'service', 6033),
  ('EFUSE_w021_TaskSchedulerError', 'Model S 2012-2020;Model X 2015-2020', 'Task could not be scheduled because it was already running or pending.', 'Next reboot, or after 5min of no scheduling errors.', 'If a task was not able to run at the appropriate time.', 'Failure to run tasks on schedule.', 'Not Available', 'Not Available', 'service', 6034),
  ('EFUSE_w022_TaskInitError', 'Model S 2012-2020;Model X 2015-2020', 'A task init function returns with an error.', 'Next reboot after alert is present.', 'If a task failed to initialize.', 'If an init routine fails, software may not opperate correctly.', 'Not Available', 'Not Available', 'service', 6035),
  ('EFUSE_w041_HighCPULoad', 'Model S 2012-2020;Model X 2015-2020', 'CPU load exceeds 80%.', 'CPU load does not exceed 80%.', 'CPU under heavy load.', 'High CPU load can indicate ineffecient code.', 'Not Available', 'Not Available', 'service', 6036),
  ('EFUSE_w042_HighStackUsage', 'Model S 2012-2020;Model X 2015-2020', 'Stack usage exceeds 80% for any task.', 'Cleared at startup.', 'High stack memory usage was detected.', 'Stack overflow can occur if there is not enough stack space.', 'Not Available', 'Not Available', 'service', 6037),
  ('EFUSE_w043_Task1msError', 'Model S 2012-2020;Model X 2015-2020', 'Task could not be scheduled because it was already running or pending.', 'Next reboot, or after 5min of no scheduling errors.', 'Debug information for 1ms task errors.', 'Failure to run tasks on schedule.', 'Not Available', 'Not Available', 'service', 6038),
  ('EFUSE_w044_Task10msError', 'Model S 2012-2020;Model X 2015-2020', 'Task could not be scheduled because it was already running or pending.', 'Next reboot, or after 5min of no scheduling errors.', 'Debug information for 10ms task errors.', 'Failure to run tasks on schedule.', 'Not Available', 'Not Available', 'service', 6039),
  ('EFUSE_w045_Task100msError', 'Model S 2012-2020;Model X 2015-2020', 'Task could not be scheduled because it was already running or pending.', 'Next reboot, or after 5min of no scheduling errors.', 'Debug information for 100ms task errors.', 'Failure to run tasks on schedule.', 'Not Available', 'Not Available', 'service', 6040),
  ('EFUSE_w046_Task1000msError', 'Model S 2012-2020;Model X 2015-2020', 'Task could not be scheduled because it was already running or pending.', 'Next reboot, or after 5min of no scheduling errors.', 'Debug information for 1000ms task errors.', 'Failure to run tasks on schedule.', 'Not Available', 'Not Available', 'service', 6041),
  ('EFUSE_w059_inputResistanceHigh', 'Model S 2012-2020;Model X 2015-2020', 'Estimated resistance on the input power feed to the vehicle controller is higher than expected.', 'Estimated resistance on the input power feed to the vehicle controller is no longer higher than expected.', 'A large voltage drop is detected in the input power to the vehicle controller, indicating the resistance on the input power feed to the vehicle controller is higher than expected.', 'The vehicle controller may be unavailable due to lack of adequate input power, limiting vehicle functionality or making the vehicle inoperable, with at least one other alert specific to that condition present.', 'Not Available', 'Not Available', 'service;service-fix', 6042),
  ('EFUSE_w061_XCPConnected', 'Model S 2012-2020;Model X 2015-2020', 'The XCP state machine has a connection.', 'XCP connection is no longer active.', 'Indicates an active connection to the universal measurement and calibration protocol state machine.', 'XCP is active.', 'Not Available', 'Not Available', 'service', 6043),
  ('EFUSE_w062_XCPWasConnected', 'Model S 2012-2020;Model X 2015-2020', 'The XCP state machine has a connection.', 'Next reboot after alert is present.', 'Indicates there was an active connection to the universal measurement and calibration protocol state machine.', 'XCP was active.', 'Not Available', 'Not Available', 'service', 6044),
  ('EFUSE_w063_SwitchFault', 'Model S 2012-2020;Model X 2015-2020', 'A condition is detected affecting switch functionality. Alert log signal data should provide more information on the switch affected and specific condition.', 'No condition affecting switch functionality is detected.', 'A condition affecting switch functionality has been detected.', 'The switch may not function or may not function as expected.', 'Not Available', 'Not Available', 'service', 6045),
  ('EFUSE_w064_busSleepReqTimeout', 'Model S 2012-2020;Model X 2015-2020', 'A bus has timed out and not gone to sleep within the alotted time.', 'Sleep request retry or aborting sleep.', 'Indicates if a bus has timed out of a sleep request from the network manager.', 'Excess idle energy consumption.', 'Not Available', 'Not Available', 'service', 6046),
  ('EFUSE_w127_vBatFusedEFuseTrip', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'VBat Fused High Current feed has been tripped due to an encountered fault condition.', 'Air Suspension compressor will not be provided power in a trip scenario.', 'Not Available', 'Not Available', 'service', 6047),
  ('EFUSE_w128_dcdcEFuseTrip', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'DCDC feed has been tripped due to an encountered fault condition.', 'Increased load on the 12 Volt battery to power the rest of the feeds, 12 Volt battery will not recoup charge.', 'Not Available', 'Not Available', 'service', 6048),
  ('EFUSE_w129_frunkBECEFuseTrip', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Frunk BEC EFuse has been tripped due to an encountered fault condition.', 'Power will not be provided to the ecus fed by the efuse module, through the frunk feed, major result is loss of drive.', 'Not Available', 'Not Available', 'service', 6049),
  ('EFUSE_w130_epas1EFuseTrip', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'EPAS Primary EFuse has been tripped due to an encountered fault condition.', 'Loss of power to primary feed for Electronic Power Assisted Steering System.', 'Not Available', 'Not Available', 'service', 6050),
  ('EFUSE_w131_epas2EFuseTrip', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'EPAS Secondary has been tripped due to an encountered fault condition.', 'EPAS Secondary feed will not be powered, and components connected auxillary power will no longer be powered.', 'Not Available', 'Not Available', 'service', 6051),
