  ('EPAS3S_a139_difCntError', 'Model S 2021+;Model X 2021+', 'The EPAS3S ECU receives invalid CAN messages from the DIF ECU on the Chassis CAN bus.', 'The EPAS3S ECU begins receiving valid CAN messages from the DIF ECU on the Chassis CAN bus again.', 'The secondary Electronic Power Assist Steering (EPAS3S) electronic control unit (ECU) receives invalid controller area network (CAN) messages from the front drive inverter (DIF) ECU on the Chassis CAN bus.', 'Steering assist may be reduced or may not function as expected.', 'Not Available', 'Not Available', 'service', 6820),
  ('EPAS3S_a140_difCsError', 'Model S 2021+;Model X 2021+', 'The EPAS3S ECU receives invalid CAN messages from the DIF ECU on the Chassis CAN bus.', 'The EPAS3S ECU begins receiving valid CAN messages from the DIF ECU on the Chassis CAN bus.', 'The secondary Electronic Power Assist Steering (EPAS3S) electronic control unit (ECU) receives invalid controller area network (CAN) messages from the front drive inverter (DIF) ECU on the Chassis CAN bus.', 'Steering assist may be reduced or may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 6821),
  ('EPAS3S_a142_vcsecCntError', 'Model S 2021+;Model X 2021+', 'CAN message counter received from the VCSEC ECU does not increment as expected.', 'CAN message counter received from the VCSEC ECU increments as expected.', 'Controller Area Network (CAN) message received from the vehicle security controller (VCSEC) electronic control unit (ECU) has an invalid counter value, indicating an error in data integrity has been detected.', 'The VCSEC to Electronic Power-Assisted Steering (EPAS) interface is interrupted. Tire-based steering tuning may be affected.', 'Not Available', 'Not Available', 'service', 6822),
