  ('FC_w289_GB_proxTimeout', 'Model S 2012-2020;Model X 2015-2020', 'The proximity status detected by the GB adapter is not latched after power on for 3 seconds.', 'Detected proximity status is latched.', 'The Fast Charge (FC) Electronic Control Unit (ECU) has detected a timeout condition after the GuoBiao (GB) Adapter proximity status did not report as latched for 3 seconds after power on.', 'Charging session may not start.', 'Not Available', 'Not Available', 'service', 8290),
  ('FC_w290_GB_pilotAcceptTimeout', 'Model S 2012-2020;Model X 2015-2020', 'FC ECU and vehicle does not accept request from adapter within 3 seconds after the pilot signal transmits to 5 percent duty cycle.', 'Handshake request is accepted by the vehicle via pilot signal.', 'The Fast Charge (FC) Electronic Control Unit (ECU) has detected a handshake request from the GuoBiao (GB) adapter but the request was not accepted.', 'Charging session may not start.', 'Not Available', 'Not Available', 'service', 8291),
  ('FC_w291_GB_vehDataTimeout', 'Model S 2012-2020;Model X 2015-2020', 'GB adapter does not receive vehicle handshake parameters within the expected 3 second time frame, resulting in a timeout condition.', 'GB adapter receives vehicle parameters within expected time frame.', 'The Fast Charge (FC) Electronic Control Unit (ECU) has detected the vehicle was unable to send handshake parameters to the GuoBiao (GB) adapter within 3 seconds. Handshake timeouts may result in the charging session not starting.', 'Charging session may not start.', 'Not Available', 'Not Available', 'service', 8292),
