  ('GTW_w014_APSversionMismatch', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The GTW detects the APS running a different firmware version than expected.', 'The GTW no longer detects the APS running a different firmware version than expected.', 'The vehicle gateway (GTW) detects the Autopilot Processor Secondary (APS) electronic control unit (ECU) is running a firmware version that may not be compatible with the firmware installed on the rest of the vehicle.', 'Autopilot features depending on APS functionality may be limited or unavailable.', 'Not Available', 'Not Available', 'service-fix', 8438),
  ('GTW_w014_diVersionMismatch', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Drive Inverter Version Mismatch Warning', NULL, 'Software update required', 'Schedule service', 'customer', 8439),
  ('GTW_w015_DIFversionMismatch', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The GTW detects the DIF running a different firmware version than expected.', 'The GTW no longer detects the DIF running a different firmware version than expected.', 'The vehicle gateway (GTW) detects the front drive inverter (DIF) electronic control unit (ECU) is running a firmware version that may not be compatible with the firmware installed on the rest of the vehicle.', 'Vehicle is unable to drive until the firmware version mismatch is resolved, to make sure front drive unit functionality is not limited or unavailable due to firmware. Inability to use waste heat to supplement high voltage battery heating may make charging at colder temperatures limited or unavailable.', 'Incompatible drive system software detected', 'Schedule service - Unable to drive until updated', 'customer;service-fix', 8440),
  ('GTW_w015_cpVersionMismatch', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Charge Port Version Mismatch Warning', NULL, 'Software update required', 'Schedule service', 'customer;service', 8441),
  ('GTW_w016_BLEEPCENTERversionMismatch', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The GTW detects the BLEEPCENTER ECU running a different firmware version than expected.', 'The GTW no longer detects the BLEEPCENTER ECU running a different firmware version than expected.', 'The vehicle gateway (GTW) detects the Bluetooth Low Energy End Point Center (BLEEPCENTER) electronic control unit (ECU) is running a firmware version that may not be compatible with the firmware installed on the rest of the vehicle.', 'Features depending on Bluetooth connectivity via BLEEPCENTER functionality, including Near Field Communication (NFC) key and phone-as-key reading, may be limited or unavailable.', 'Not Available', 'Not Available', 'service-fix', 8442),
  ('GTW_w016_chgVersionMismatch', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'Charger Version Mismatch Warning', NULL, 'Software update required', 'Schedule service', 'customer;service', 8443),
  ('GTW_w017_BMSversionMismatch', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+;Semitruck', 'The GTW detects the high voltage BMS running a different firmware version than expected.', 'The GTW no longer detects the high voltage BMS running a different firmware version than expected.', 'The vehicle gateway (GTW) detects the high voltage Battery Management System (BMS) electronic control unit (ECU) is running a firmware version that may not be compatible with the firmware installed on the rest of the vehicle.', 'Vehicle is unable to drive, charge, or support the low voltage battery / electrical system until the firmware version mismatch is resolved, to make sure high voltage battery functionality is not limited or unavailable due to firmware.', 'Incompatible drive system software detected', 'Schedule service - Unable to drive until updated', 'customer;service-fix', 8444),
  ('GTW_w017_accLoadShed', 'Model S 2012-2020;Model X 2015-2020', NULL, NULL, 'GTW_w017_accLoadShed', NULL, 'Electrical system power reduced', 'Vehicle may shut down unexpectedly', 'customer;service', 8445),
  ('GTW_w018_CMPversionMismatch', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The GTW detects the CMP ECU running a different firmware version than expected.', 'The GTW no longer detects the CMP ECU running a different firmware version than expected.', 'The vehicle gateway (GTW) detects the air conditioning compressor (CMP) electronic control unit (ECU) is running a firmware version that may not be compatible with the firmware installed on the rest of the vehicle.', 'Thermal management system features depending on air conditioning compressor functionality may be limited or unavailable.', 'Not Available', 'Not Available', 'service-fix', 8446),
