  ('HVBATT_a302_PowershareMaxVoltageViolation', 'Cybertruck', 'The voltage exceeds the limit for the HV battery while powersharing.', 'Clears automatically.', 'The Battery Management System (BMS) detects the voltage limit for the high voltage (HV) battery is exceeded while powersharing.', 'The active Vehicle to Home / Grid / Load / Vehicle (V2X) or outlet session will be terminated, and future sessions will be unavailable.', 'Not Available', 'Not Available', 'service', 9165),
  ('HVBATT_a303_PowershareMinVoltageViolation', 'Cybertruck', 'The voltage exceeds the limit for the HV battery while powersharing.', 'Clears automatically.', 'The Battery Management System (BMS) detects the voltage limit for the high voltage (HV) battery is exceeded while powersharing.', 'The active Vehicle to Home / Grid / Load / Vehicle (V2X) or outlet session will be terminated, and future sessions will be unavailable.', 'Not Available', 'Not Available', 'service', 9166),
  ('HVBATT_a304_PowershareExternalChargeRegulation', 'Cybertruck', 'The BMS detects a condition with the external charge regulation while powersharing.', 'Clears automatically.', 'The Battery Management System (BMS) detects a condition with the external charge regulation while powersharing.', 'The active Vehicle to Home / Grid / Load / Vehicle (V2X) or outlet session will be terminated, and future sessions will be unavailable.', 'Not Available', 'Not Available', 'service', 9167),
  ('HVBATT_a305_PowershareMaxBrickVoltageViolation', 'Cybertruck', 'A brick voltage exceeds the maximum threshold while powersharing.', 'Clears automatically.', 'The Battery Management System (BMS) detects a brick voltage that exceeds the maximum threshold while powersharing.', 'The active Vehicle to Home / Grid / Load / Vehicle (V2X) or outlet session will be terminated, and future sessions will be unavailable.', 'Not Available', 'Not Available', 'service', 9168),
