  ('IDB_a084_EPAS3PsysStatusDLC', 'Model Y 2025+', 'EPAS3P_sysStatus is not received for longer than 100 milliseconds or EPAS3P_sysStatus is received with incorrect data length for longer than 100 milliseconds.', 'Clears when EPAS3P_sysStatus Controller Area Network (CAN) message is received with correct data length for 100 milliseconds.', 'EPAS3P system status message EPAS3P_sysStatus was not received or message length is incorrect.', 'There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus.', 'Not Available', 'Not Available', 'service-fix', 10015),
  ('IDB_a085_EPAS3PsysStatusChecksum', 'Model Y 2025+', 'EPAS3P_sysStatus is received with incorrect CRC for longer than 100 milliseconds.', 'Clears when EPAS3P_sysStatus Controller Area Network (CAN) message is received with correct Cyclic Redundancy Check (CRC) for 100 milliseconds.', 'EPAS3P system status message EPAS3P_sysStatus checksum is incorrect.', 'There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus.', 'Not Available', 'Not Available', 'service-fix', 10016),
