  ('IDB_a087_PMstate2DLC', 'Model Y 2025+', 'PM_state2 is not received for longer than 200 milliseconds or PM_state2 is received with incorrect data length for longer than 200 milliseconds.', 'Clears when PM_state2 Controller Area Network (CAN) message is received with correct data length for 200 milliseconds.', 'PM state 2 message PM_state2 was not received or message length is incorrect.', 'Brake Traction Control (BTC), Vehicle Dynamics Control (VDC), Brake Disc Wipe (BDW), and External Brake Request (EBR) may be unavailable. There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus. The vehicle should be driven with extreme caution.', 'Not Available', 'Not Available', 'service-fix', 10018),
  ('IDB_a088_PMstate2Checksum', 'Model Y 2025+', 'PM_state2 is received with incorrect CRC for longer than 200 milliseconds.', 'Clears when PM_state2 Controller Area Network (CAN) message is received with correct Cyclic Redundancy Check (CRC) for 200 milliseconds.', 'PM state 2 message PM_state2 checksum is incorrect.', 'Brake Traction Control (BTC), Vehicle Dynamics Control (VDC), Brake Disc Wipe (BDW), and External Brake Request (EBR) may be unavailable. There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus. The vehicle should be driven with extreme caution.', 'Not Available', 'Not Available', 'service-fix', 10019),
  ('IDB_a089_PMstate2Counter', 'Model Y 2025+', 'PM_state2 is received with incorrectly incrementing counter for longer than 200 milliseconds.', 'Clears when PM_state2 Controller Area Network (CAN) message is received with correctly incrementing counter for 200 milliseconds.', 'PM state 2 message PM_state2 counter is incorrect.', 'Brake Traction Control (BTC), Vehicle Dynamics Control (VDC), Brake Disc Wipe (BDW), and External Brake Request (EBR) may be unavailable. There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus. The vehicle should be driven with extreme caution.', 'Not Available', 'Not Available', 'service-fix', 10020),
  ('IDB_a090_RCMinertial1DLC', 'Model Y 2025+', 'RCM_inertial1 is not received for longer than 100 milliseconds or RCM_inertial1 is received with incorrect data length for longer than 100 milliseconds.', 'Clears when RCM_inertial1 Controller Area Network (CAN) message is received with correct data length for 100 milliseconds.', 'RCM inertial 1 message RCM_inertial1 was not received or message length is incorrect.', 'There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus.', 'Not Available', 'Not Available', 'service-fix', 10021),
  ('IDB_a091_RCMinertial1Checksum', 'Model Y 2025+', 'RCM_inertial1 is received with incorrect CRC for longer than 100 milliseconds.', 'Clears when RCM_inertial1 Controller Area Network (CAN) message is received with correct Cyclic Redundancy Check (CRC) for 100 milliseconds.', 'RCM inertial 1 message RCM_inertial1 checksum is incorrect.', 'There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus.', 'Not Available', 'Not Available', 'service-fix', 10022),
  ('IDB_a092_RCMinertial1Counter', 'Model Y 2025+', 'RCM_inertial1 is received with incorrectly incrementing counter for longer than 100 milliseconds.', 'Clears when RCM_inertial1 Controller Area Network (CAN) message is received with correctly incrementing counter for 100 milliseconds.', 'RCM inertial 1 message RCM_inertial1 counter is incorrect.', 'There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus.', 'Not Available', 'Not Available', 'service-fix', 10023),
  ('IDB_a093_RCMinertial2DLC', 'Model Y 2025+', 'RCM_inertial2 is not received for longer than 100 milliseconds or RCM_inertial2 is received with incorrect data length for longer than 100 milliseconds.', 'Clears when RCM_inertial2 Controller Area Network (CAN) message is received with correct data length for 100 milliseconds.', 'RCM inertial 2 message RCM_inertial2 was not received or message length is incorrect.', 'Anti-lock Brake System (ABS), Controlled Deceleration via Parking brake (CDP), External Brake Request (EBR), and Secondary Collision Mitigation (SCM) may be unavailable. There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus. The vehicle should be driven with extreme caution.', 'ABS (anti-lock braking system) disabled', 'Drive with caution', 'customer;service-fix', 10024),
  ('IDB_a094_RCMinertial2Checksum', 'Model Y 2025+', 'RCM_inertial2 is received with incorrect CRC for longer than 100 milliseconds.', 'Clears when RCM_inertial2 Controller Area Network (CAN) message is received with correct Cyclic Redundancy Check (CRC) for 100 milliseconds.', 'RCM inertial 2 message RCM_inertial2 checksum is incorrect.', 'Anti-lock Brake System (ABS), Controlled Deceleration via Parking brake (CDP), External Brake Request (EBR), and Secondary Collision Mitigation (SCM) may be unavailable. There may be an issue with the transmitting Electronic Control Unit (ECU) or CAN bus. The vehicle should be driven with extreme caution.', 'ABS (anti-lock braking system) disabled', 'Drive with caution', 'customer;service-fix', 10025),
