  ('PEPSM_a071_SEPS_MIA', 'Cybertruck', 'One or more of the expected messages from the SEPS ECU is not received.', 'The vehicle controller starts receiving the expected messages from the SEPS ECU.', 'One or more of the messages the vehicle controller receives periodically from the Secondary Electric Power Steering (SEPS) electronic control unit (ECU) is not received, indicating the SEPS ECU may be unavailable (MIA).', 'Power steering may be limited or unavailable.', 'Not Available', 'Not Available', 'service', 10684),
  ('PEPSM_a072_PEPS_MIA', 'Cybertruck', 'One or more of the expected messages from the PEPS ECU is not received.', 'The vehicle controller starts receiving the expected messages from the PEPS ECU.', 'One or more of the messages the vehicle controller receives periodically from the Primary Electric Power Steering (PEPS) electronic control unit (ECU) is not received, indicating the PEPS ECU may be unavailable (MIA).', 'Power steering may be limited or unavailable.', 'Not Available', 'Not Available', 'service', 10685),
