INSERT OR IGNORE INTO tesla_alert_catalog (signal_name, models, condition, clear_condition, description, potential_impact, customer_message_1, customer_message_2, audiences, source_row) VALUES
  ('RSA_a115_VCRIGHT1_MIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the VCRIGHT1 within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the VCRIGHT1.', 'One or more of the messages the vehicle controller receives periodically from the right vehicle controller (VCRIGHT1) is not received, indicating the VCRIGHT1 may be unavailable (MIA).', 'Vehicle functions that depend on the VCRIGHT1 may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 13002),
