  ('SEPSM_a128_VCREAR_MIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the VCREAR within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the VCREAR.', 'One or more of the messages the vehicle controller receives periodically from the rear vehicle controller (VCREAR) is not received, indicating the VCREAR may be unavailable (MIA).', 'Vehicle functions that depend on the VCREAR may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service-fix', 13321),
  ('SEPSM_a135_motorUncalibrated', 'Cybertruck', 'The monitor detects motor calibration is incomplete.', 'Calibration of motor.', 'The monitor is missing calibration data for the motor.', 'Torque from motor is unavailable.', 'Not Available', 'Not Available', 'service-fix', 13322),
  ('SEPSM_a136_motorCalibrationMismatch', 'Cybertruck', 'Controller and monitor handwheel calibration data not matching.', 'Controller and monitor handwheel calibration data matching.', 'The motor calibration data does not match across controller and monitor.', 'Torque from motor is unavailable.', 'Not Available', 'Not Available', 'service-fix', 13323),
  ('SEPSM_a137_rackUncalibrated', 'Cybertruck', 'Uncalibrated front steering rack detected.', 'Front steering rack calibration detected.', 'The Electronic Power Steering (EPS) monitor is missing calibration data for the steering rack.', 'Steering control from this node is disabled.', 'Not Available', 'Not Available', 'service-fix', 13324),
  ('SEPSM_a138_rackCalibrationMismatch', 'Cybertruck', 'Controller and monitor rack calibration data not matching.', 'Controller and monitor rack calibration data matching.', 'The rack calibration data does not match across controller and monitor.', 'Steering control from this node is disabled.', 'Not Available', 'Not Available', 'service-fix', 13325),
