  ('SEPSM_a159_preloadTorqueError', 'Cybertruck', 'The force produced on the rack is greater than the max allowed rack force during preload.', 'The controller is performing preload torque with specified max rack force.', 'The monitor detected an error in the torque production of its paired controller.', 'Steering redundancy will be unavailable.', 'Not Available', 'Not Available', 'service', 13331),
  ('SEPSM_a163_calibrationFault', 'Cybertruck', 'One or more modules not calibrated or calibration values do not match controller values.', 'All modules calibrated and calibration values match controller values.', 'The steering monitor detected an error affecting its calibration.', 'Steering redundancy will be unavailable.', 'Not Available', 'Not Available', 'service-fix', 13332),
  ('SEPSM_a208_startupSequenceFailed2', 'Cybertruck', 'Monitor calibration check is unsuccessful, corresponding controller is not responding, or state timeout occurs.', 'Startup sequence passes. Startup sequence is run during vehicle startup, and the condition may resolve by drive cycling the vehicle.', 'Power steering startup sequence is unsuccessful.', 'The motor is disqualified and system health is degraded.', 'Not Available', 'Not Available', 'service-fix', 13333),
