INSERT OR IGNORE INTO tesla_alert_catalog (signal_name, models, condition, clear_condition, description, potential_impact, customer_message_1, customer_message_2, audiences, source_row) VALUES
  ('VCRIGHT_a251_seatUncalTrack', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The seat track motor is detected as uncalibrated (calibrated state of the seat track motor is 0).', 'The seat track motor is calibrated.', 'The seat track motor is not calibrated, which may cause position recall to be unavailable.', 'Position recall may be unavailable, meaning the preset user preferences for seat positions may also be unavailable.', 'Not Available', 'Not Available', 'service-fix', 17502),
  ('VCRIGHT_a252_seatUncalBack', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Motor calibrated is 0', 'The motor is calibrated', 'The backrest motor is uncalibrated.', 'Position recall unavailable', 'Not Available', 'Not Available', 'service-fix', 17503),
  ('VCRIGHT_a253_seatUncalTilt', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Motor calibrated is 0', 'The motor is calibrated', 'The tilt motor is uncalibrated.', 'Position recall unavailable', 'Not Available', 'Not Available', 'service-fix', 17504),
  ('VCRIGHT_a254_seatUncalLift', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Motor calibrated is 0', 'The motor is calibrated', 'The lift motor is uncalibrated.', 'Position recall unavailable', 'Not Available', 'Not Available', 'service-fix', 17505),
  ('VCRIGHT_a255_PTCOverTemp', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The positive temperature coefficient (PTC) heater experienced an over-temperature condition and shut down.', 'The positive temperature coefficient (PTC) heater is no longer experiencing over-temperature condition.', 'The heating, ventilation, air-conditioning (HVAC) system positive temperature coefficient (PTC) heater is experiencing an over-temperature condition and will shut off until it cools down. This may cause a reduction in HVAC heating performance.', 'There may be a reduction in heating performance for the heating, ventilation, air-conditioning (HVAC) system.', 'Not Available', 'Not Available', 'service-fix', 17506),
  ('VCRIGHT_a256_PTCCurrentDrawNoReq', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'PTC heater is consuming current when it was not commanded', 'PTC heater is no longer consuming current when not commanded', 'HVAC PTC heater is drawing current when not requested.', 'May result in reduced HVAC heating performance', 'Not Available', 'Not Available', 'service-fix', 17507),
  ('VCRIGHT_a257_THSMIA', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'THS ECU is not reporting on LIN.', 'THS ECU is reporting on LIN.', 'Temperature Humidity Sensor (THS) ECU is not responding over Local Interconnect Network (LIN).', 'Heating, Ventilation, Air-Conditioning (HVAC) auto functionality will be compromised.', 'Not Available', 'Not Available', 'service-fix', 17508),
  ('VCRIGHT_a258_PTCStuckInBoot', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'PTC is sending out boot ID when not intended, indicating that it is stuck in bootloader', 'PTC is not longer sending out boot ID', 'PTC heater stuck in bootloader due to high current at startup.', 'May result in reduced HVAC heating performance', 'Not Available', 'Not Available', 'service-fix', 17509),
  ('VCRIGHT_a258_rightHeadlampNotAimed', 'Cybertruck', 'A replacement right vehicle controller (VCRIGHT) has been installed.', 'The headlights are aimed using the user interface (UI) or the headlight aiming ODIN routine is run for the right headlight.', 'The vehicle controller detects that the right headlight has not been aimed or requires re-aiming.', 'The headlights may not properly illuminate the area in front of the vehicle or may dazzle oncoming drivers.', 'Not Available', 'Not Available', 'service-fix', 17510),
  ('VCRIGHT_a261_emergencyLatchRelRear', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Door opened without electronic release', 'Door is closed', 'The mechanical release was used to open the door.', 'Posible trim damage', 'Not Available', 'Not Available', 'service', 17511),
  ('VCRIGHT_a262_PTCFaulted', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'One of the faults on the PTC heater is active', 'No faults on the PTC heater are active', 'PTC heater is faulted due to the reason set in the alert context data.', 'This may result in reduced HVAC heating performance', 'Not Available', 'Not Available', 'service-fix', 17512),
  ('VCRIGHT_a263_USBMIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the VCUSB within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the VCUSB.', 'One or more of the messages the vehicle controller receives periodically from the usb vehicle controller (VCUSB) is not received, indicating the VCUSB may be unavailable (MIA).', 'Rear airwaves and USB ports will not be functioning', 'Not Available', 'Not Available', 'service-fix', 17513),
  ('VCRIGHT_a267_seatTrackHCEncStlDbg', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Current draw exceeded 70% of the stall limit, and the encoder did not move for 100ms.', 'The motor is not in a movement state. It may also be in a movement state, but has not detected a high current motor stall.', 'The seat track motor encoder has unexpectedly stalled.', 'The seat track motor encoder may increment incorrectly if an obstruction is encountered.', 'Not Available', 'Not Available', 'service', 17514),
  ('VCRIGHT_a268_seatBackHCEncStlDbg', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Current draw exceeds 70% of stall limit and encoder not moving for 100ms', 'The motor is not in a movement state or it is but has not detected high current motor stall', 'The backrest motor encoder has unexpectedly stalled.', 'Encoder may increment incorrectly if obstruction encountered', 'Not Available', 'Not Available', 'service', 17515),
  ('VCRIGHT_a269_seatTiltHCEncStlDbg', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Current draw exceeds 70% of the stall limit, and the encoder does not move for 100ms.', 'The motor is not in a movement state. It may also be in a movement state, but has not detected a high current motor stall.', 'The seat tilt motor encoder has unexpectedly stalled.', 'The seat tilt motor encoder may increment incorrectly if an obstruction is encountered.', 'Not Available', 'Not Available', 'service', 17516),
  ('VCRIGHT_a270_seatLiftHCEncStlDbg', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Current draw exceeds 70% of the stall limit, and the encoder does not move for 100ms.', 'The motor is not in a movement state. It may also be in a movement state, but has not detected a high current motor stall.', 'The seat lift motor encoder has unexpectedly stalled.', 'The seat lift motor encoder may increment incorrectly if an obstruction is encountered.', 'Not Available', 'Not Available', 'service', 17517),
  ('VCRIGHT_a271_THSSensorFault', 'Cybertruck;Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'One or more sensors on the THS is reporting a condition and not working as expected.', 'Sensors on the THS are not reporting any conditions and working as expected.', 'Temperature Humidity Sensor (THS) is reporting Signal Not Available (SNA) for at least one of its sensor values.', 'Heating, Ventilation, Air-Conditioning (HVAC) system will not work nominally.', 'Not Available', 'Not Available', 'service-fix', 17518),
  ('VCRIGHT_a273_handleStuckActiveF', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The handle has been unseated for at least 5 minutes', 'Front handle no longer active', 'Front handle is stuck unseated, vehicle will not sleep.', 'Vehicle will not sleep due to handle(s) being active', 'Not Available', 'Not Available', 'service', 17519),
  ('VCRIGHT_a274_handleStuckActiveR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The handle has been unseated for at least 5 minutes', 'Rear handle no longer active', 'Rear handle is stuck unseated, vehicle will not sleep.', 'Vehicle will not sleep due to handle(s) being active', 'Not Available', 'Not Available', 'service', 17520),
  ('VCRIGHT_a275_rightTurnLightFault', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped', 'A fault has been detected with the rear right turn indicator.', 'The rear right turn indicator may not be working. Working turn indicators on that side will blink at double the speed.', 'Not Available', 'Not Available', 'service', 17521),
  ('VCRIGHT_a278_hvacPtcHeatingUnavailable', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'PTC heater is not reporting on CAN, or is receiving low voltage from the HV battery', 'PTC heater is on CAN, and is receiving the correct voltage from the HV battery', 'Cabin heating is unavailable. Check context data for this alert and/or VCRIGHT_a262 to determine exact issue.', 'Cabin heating will not function.', 'Cabin heating currently unavailable', 'Not Available', 'customer;service-fix', 17522),
  ('VCRIGHT_a280_latchDidNotDisarmF', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The latch home switch remained active during a successful release actuation.', 'The latch starts a new release actuation.', 'The latch did not disarm during a successful release actuation.', 'The latch home switch may be incorrectly reporting its state. ', 'Not Available', 'Not Available', 'service', 17523),
  ('VCRIGHT_a281_latchDidNotDisarmR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The latch home switch remained active during a successful release actuation.', 'The latch starts a new release actuation.', 'The latch did not disarm during a successful release actuation.', 'The latch home switch may be incorrectly reporting its state. ', 'Not Available', 'Not Available', 'service', 17524),
  ('VCRIGHT_a282_latchUnexpectedArmF', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The latch home switch returned to active state after going inactive during release.', 'The latch starts a new release actuation.', 'The latch unexpectedly re-armed while releasing.', 'The latch home switch may be incorrectly reporting its state, or the latch may be over extending.', 'Not Available', 'Not Available', 'service', 17525),
  ('VCRIGHT_a283_latchUnexpectedArmR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The latch home switch returned to active state after going inactive while releasing.', 'The latch starts a new release actuation.', 'The latch unexpectedly re-armed while releasing.', 'The latch home switch may be incorrectly reporting its state, or the latch may be over extending.', 'Not Available', 'Not Available', 'service', 17526),
  ('VCRIGHT_a284_gloveboxUnderCurrentDetected', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Glovebox current draw failed to exceed minimum current requirement', 'The alert will be cleared the next time when the glovebox is actuated.', 'Glovebox current did not exceed expected mininum current requirement, likely indicating that the glovebox is not plugged in.', 'Glovebox disabled or not operational', 'Not Available', 'Not Available', 'service', 17527),
  ('VCRIGHT_a285_gloveboxOverCurrentDetected', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Glovebox current draw exceeded maximum current limit', 'The alert will be cleared the next time when the glovebox is actuated', 'Glovebox current exceeded expected maximum current, likely indicating that the glovebox connection is short-circuited.', 'Glovebox disabled or not operational', 'Not Available', 'Not Available', 'service', 17528),
  ('VCRIGHT_a285_seatHeatOverCurrFront', 'Cybertruck', 'Seat heater current has reached above a permitted threshold.', 'ECU reset or power cycle.', 'The seat heater has had unusually high current draw.', 'Seat heater will stop running. Potential damage to harness and seat.', 'Not Available', 'Not Available', 'service', 17529),
  ('VCRIGHT_a286_seatHeatHSDErrorFront', 'Cybertruck', 'The high side driver (HSD) for the front seat heater detects an error condition (overcurrent, short to ground, or thermal shutdown).', 'The error condition affecting the front seat heater is detected by the high side driver (HSD) as resolved.', 'The high side driver (HSD) for the front seat heater has detected an error condition, which may lead to the seat heater not performing as designed.', 'The front seat heater may not perform as designed.', 'Not Available', 'Not Available', 'service', 17530),
  ('VCRIGHT_a287_seatHeatDisabledF', 'Cybertruck', 'The seat heater duty cycle was set at 100% for 30 minutes.', 'The ECU is reset or power cycled.', 'The front seat heater is not heating as expected.', 'Front seat heater will be unavailable.', 'Not Available', 'Not Available', 'service', 17531),
  ('VCRIGHT_a290_occupancyFaultedFront', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Occupancy sensor is out of spec', 'Occupancy sensor voltage is not faulted or disconnected', 'The front seat occupancy sensor is faulted.', 'Cannot determine occupancy of the seat', 'Not Available', 'Not Available', 'service-fix', 17532),
  ('VCRIGHT_a291_buckleFaultedFront', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Buckle sensor is out of spec', 'Buckle sensor voltage is not faulted or disconnected', 'The front seat buckle sensor is faulted.', 'Cannot determine buckle of the seat', 'Not Available', 'Not Available', 'service-fix', 17533),
  ('VCRIGHT_a292_buckleFaultedRearC', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Buckle sensor is out of spec', 'Buckle sensor voltage is not faulted or disconnected', 'The rear center seat buckle sensor is faulted.', 'Cannot determine buckle of the seat', 'Not Available', 'Not Available', 'service', 17534),
  ('VCRIGHT_a293_buckleFaultedRearR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Buckle sensor is out of spec', 'Buckle sensor voltage is not faulted or disconnected', 'The rear right seat buckle sensor is faulted.', 'Cannot determine buckle of the seat', 'Not Available', 'Not Available', 'service', 17535),
  ('VCRIGHT_a294_occupancyFaultedRearR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Occupancy sensor is out of spec', 'Occupancy sensor voltage is not faulted or disconnected', 'The rear right seat occupancy sensor is faulted.', 'Cannot determine occupancy of the seat', 'Not Available', 'Not Available', 'service-fix', 17536),
  ('VCRIGHT_a295_occupancyFaulted3RowL', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Occupancy sensor is out of spec', 'Occupancy sensor voltage is not faulted or disconnected', 'The rear right seat occupancy sensor is faulted.', 'Cannot determine occupancy of the seat', 'Not Available', 'Not Available', 'service-fix', 17537),
  ('VCRIGHT_a295_seatBelowMinPumpTmp', 'Cybertruck', 'The measured cabin temperature is below the minimum pump temperature', 'The measured cabin temperature is above or equal to the minimum pump temperature', 'The cabin temperature is below the minimum pump temperature.', 'The pump will be disabled', 'Not Available', 'Not Available', 'service', 17538),
  ('VCRIGHT_a296_occupancyFaulted3RowR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Occupancy sensor is out of spec', 'Occupancy sensor voltage is not faulted or disconnected', 'The rear right seat occupancy sensor is faulted.', 'Cannot determine occupancy of the seat', 'Not Available', 'Not Available', 'service-fix', 17539),
  ('VCRIGHT_a297_seatBelowMinPumpTmp', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The measured cabin temperature is below the minimum pump temperature', 'The measured cabin temperature is above or equal to the minimum pump temperature', 'The cabin temperature is below the minimum pump temperature.', 'The pump will be disabled', 'Not Available', 'Not Available', 'service', 17540),
  ('VCRIGHT_a298_buckleFaulted3RowL', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Buckle sensor is out of spec', 'Buckle sensor voltage is not faulted or disconnected', 'The rear right seat buckle sensor is faulted.', 'Cannot determine buckle of the seat', 'Not Available', 'Not Available', 'service', 17541),
  ('VCRIGHT_a299_buckleFaulted3RowR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Buckle sensor is out of spec', 'Buckle sensor voltage is not faulted or disconnected', 'The rear right seat buckle sensor is faulted.', 'Cannot determine buckle of the seat', 'Not Available', 'Not Available', 'service', 17542),
  ('VCRIGHT_a302_airwaveRightVerticalUnavailable', 'Model 3 2024+;Model Y 2025+', 'A condition affecting right vertical airwave actuator is detected.', 'Successful HVAC actuator calibration or clear actuator blockages.', 'A condition affecting right vertical airwave cabin HVAC actuator functionality has been detected.', 'Right vertical airwave is unable to move up and down.', 'Not Available', 'Not Available', 'service-fix', 17543),
  ('VCRIGHT_a302_blowerGeneralFault', 'Model S 2021+;Model X 2021+', 'Any of the alert log signals is set (=1), indicating VCRIGHT detects a condition affecting blower motor functionality.', 'The VCRIGHT integrated circuit controlling blower motor function no longer detects a condition affecting functionality.', 'The brushless HVAC blower motor has experienced a condition affecting functionality. The HVAC blower will not function, and the blower motor driver in the right vehicle controller (VCRIGHT) will be reset to attempt to clear the condition. Note: The reset may only temporarily clear the condition, depending on the cause. For example, the condition will quickly return if the cause is a broken wire or loose connection.', 'The HVAC blower will not function. The VCRIGHT blower motor driver will be reset to attempt to clear the condition affecting functionality.', 'Not Available', 'Not Available', 'service-fix', 17544),
  ('VCRIGHT_a303_eFuseMgmtWindowLift', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'VCRIGHT detects an eFuse overcurrent event (or a trip) on the window bridges power feed. Voltage is above 8V for 200ms on at least one of the right window motor outputs while no outputs are being driven.', 'Alert clears automatically after 10 seconds. If alert asserts for a maximum of three times, loads will be disabled. VCRIGHT may require a reset.', 'The window motors are disabled. The Right Vehicle Controller (VCRIGHT) Electronic Control Unit (ECU) detects an eFuse overcurrent event on the window bridge power feed.', 'Window control is disabled. Right window motor may not operate as expected.', 'Not Available', 'Not Available', 'service', 17545),
  ('VCRIGHT_a306_handleDisconnectedF', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Handle has just become reconnected or has been disconnected for longer than 1 second', 'Handle no longer reports disconnected', 'Front exterior handle reported disconnected.', 'If this alert persists the exterior handle may not work', 'Not Available', 'Not Available', 'service-fix', 17546),
  ('VCRIGHT_a307_handleDisconnectedR', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Handle has just become reconnected or has been disconnected for longer than 1 second', 'Handle no longer reports disconnected', 'Rear exterior handle reported disconnected.', 'If this alert persists the exterior handle may not work', 'Not Available', 'Not Available', 'service-fix', 17547),
  ('VCRIGHT_a308_airwaveRightLateralUnavailable', 'Model 3 2024+;Model Y 2025+', 'A condition affecting right lateral airwave actuator is detected.', 'Successful HVAC actuator calibration or clear actuator blockages.', 'A condition affecting right lateral airwave cabin HVAC actuator functionality has been detected.', 'Right lateral airwave is unable to move left and right.', 'Not Available', 'Not Available', 'service-fix', 17548),
  ('VCRIGHT_a310_mirrorFoldStall', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'If folding motor current exceeds 0.5A or decreases below 0.1A after 500ms from beginning of actuation. Or timeout from current state after 5 seconds.', 'Successful mirror fold or unfold', 'Mirror stalled unexpectedly while folding or unfolding.', 'Mirror might be halfway between folded and unfolded', 'Not Available', 'Not Available', 'service', 17549),
  ('VCRIGHT_a311_rightBrakeLightFault', 'Model S 2021+;Model X 2021+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped', 'A fault has been detected with the right brake light.', 'The right brake light may not be working.', 'Not Available', 'Not Available', 'service', 17550),
  ('VCRIGHT_a311_rightBrakeLightFault', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its eFuse is tripped.', 'The light is plugged in, draws current when on, and its eFuse is not tripped.', 'A fault has been detected with the right brake light.', 'The right brake light may not be working.', 'Not Available', 'Not Available', 'service', 17551),
  ('VCRIGHT_a312_rightTailLightFault', 'Model S 2021+;Model X 2021+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped.', 'A fault has been detected with the right tail light. Model 3: this includes right body-side tail, left+right liftgate tail, and license plate lights. Model Y: this includes right body-side tail and right liftgate tail lamps.', 'The right tail light may not be working.', 'Not Available', 'Not Available', 'service', 17552),
  ('VCRIGHT_a312_rightTailLightFault', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its eFuse is tripped.', 'The light is plugged in, draws current when on, and its eFuse is not tripped.', 'A fault has been detected with the right tail light. Model 3: this includes right body-side tail, left+right liftgate tail, and license plate lights. Model Y: this includes right body-side tail and right liftgate tail lamps.', 'The right tail light may not be working.', 'Not Available', 'Not Available', 'service', 17553),
  ('VCRIGHT_a313_rightFootwellLightFault', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped', 'A fault has been detected with the right footwell light.', 'The right footwell light may not be working.', 'Not Available', 'Not Available', 'service', 17554),
  ('VCRIGHT_a314_rightMapPocketLightFault', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped', 'A fault has been detected with the right map pocket light.', 'The right map pocket light may not be working.', 'Not Available', 'Not Available', 'service', 17555),
  ('VCRIGHT_a315_rightInteriorTrunkLightFault', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its efuse is tripped', 'The light is plugged in, draws current when on, and its efuse is not tripped', 'A fault has been detected with the right interior trunk light.', 'The right interior trunk light may not be working.', 'Not Available', 'Not Available', 'service', 17556),
  ('VCRIGHT_a316_mirrorPrematureFoldStall', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Sets if the mirror folding motor current exceeds 0.5A at some point, but then decreases to below 0.1A between 200ms - 1750ms after the beginning of actuation. Also sets at the end of the retry actuation to capture/log additional data.', 'Clears after 10ms.', 'A side-view mirror started a fold or unfold movement, but then stalled before finishing the movement. The mirror will attempt 1 retry to complete the movement.', 'The mirror will stop for 400ms before attempting the retry. If the mirror unexpectedly stalls again during the retry, it may be left partially folded/unfolded.', 'Not Available', 'Not Available', 'service', 17557),
  ('VCRIGHT_a318_leftExteriorTrunkLightFault', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its eFuse is tripped.', 'The light is plugged in, draws current when on, and its eFuse is not tripped.', 'A fault has been detected with the left exterior trunk light.', 'The left exterior trunk light may not be working.', 'Not Available', 'Not Available', 'service', 17558),
  ('VCRIGHT_a319_rightExteriorTrunkLightFault', 'Model 3 2017-2023;Model 3 2024+;Model Y;Model Y 2025+', 'The light is unplugged, doesn''t draw current when on, or its eFuse is tripped.', 'The light is plugged in, draws current when on, and its eFuse is not tripped.', 'A fault has been detected with the right exterior trunk light.', 'The right exterior trunk may not be working.', 'Not Available', 'Not Available', 'service', 17559),
  ('VCRIGHT_a324_mirrorHeatFault', 'Model 3 2017-2023;Model 3 2024+;Model S 2021+;Model X 2021+;Model Y;Model Y 2025+', 'Mirror heat current was below the expected value', 'Mirror heat turned off / no longer active', 'Mirror heat undercurrent detected, indicating mirror heating may be limited or unavailable.', 'This alert is primarily informational and is used for logging purposes. No expected impact on vehicle functionality', 'Not Available', 'Not Available', 'service', 17560),
