  ('VCSEATD_a236_lumbarOverPresA', 'Model S 2012-2020;Model S 2021+;Model X 2015-2020;Model X 2021+;Semitruck', 'Bladder pressure exceeds 1300hPa (absolute)', 'Bladder A does not exceed pressure limit', 'The bladder A has exceeded pressure limits.', 'Damage to bladder or valve block', 'Not Available', 'Not Available', 'service', 17969),
  ('VCSEATD_a237_lumbarOverPresB', 'Model S 2012-2020;Model S 2021+;Model X 2015-2020;Model X 2021+;Semitruck', 'Bladder pressure exceeds 1300hPa (absolute)', 'Bladder B does not exceed pressure limit', 'The bladder B has exceeded pressure limits.', 'Damage to bladder or valve block', 'Not Available', 'Not Available', 'service', 17970),
