  ('VCTRAILER_a109_RCM_MIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the RCM within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the RCM.', 'One or more of the messages the vehicle controller receives periodically from the Restraint Control Module (RCM) is not received, indicating the RCM may be unavailable (MIA).', 'Vehicle functions that depend on the RCM may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service', 18408),
  ('VCTRAILER_a110_GTW_MIA', 'Cybertruck', 'An expected CAN message from the vehicle gateway (GTW) has not been received within the expected timeout, or the message drop rate is too high while the GTW is CAN active.', 'All expected CAN messages from the vehicle gateway (GTW) are received, or the GTW is CAN inactive.', 'One or more expected Controller Area Network (CAN) messages from the vehicle gateway (GTW) was not received. Vehicle functions  that depend on CAN messages from the GTW may be unavailable, or their performance may be affected.', 'Vehicle functions that depend on CAN messages from the vehicle gateway (GTW) may be unavailable, or their performance may be affected.', 'Not Available', 'Not Available', 'service', 18409),
  ('VCTRAILER_a111_EPBR_MIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the EPBR ECU within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the EPBR ECU.', 'One or more of the messages the vehicle controller receives periodically from the right Electronic Park Brake (EPBR) electronic control unit (ECU) is not received, indicating the EPBR ECU may be unavailable (MIA).', 'The parking brake may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service', 18410),
  ('VCTRAILER_a112_EPBL_MIA', 'Cybertruck', 'The vehicle controller does not receive one or more of the expected messages from the EPBL ECU within the expected time frame.', 'The vehicle controller starts receiving the expected messages from the EPBL ECU.', 'One or more of the messages the vehicle controller receives periodically from the left Electronic Park Brake (EPBL) electronic control unit (ECU) is not received, indicating the EPBL ECU may be unavailable (MIA).', 'The parking brake may be unavailable or may not function as expected.', 'Not Available', 'Not Available', 'service', 18411),
